rep('''                    NavigationBarItem(\n                        selected = tab == RootTab.SETTINGS,''','''                    NavigationBarItem(\n                        selected = tab == RootTab.SEARCH,\n                        onClick = { tab = RootTab.SEARCH },\n                        icon = { Icon(Icons.Default.Search, null) },\n                        label = { Text("جستجو") }\n                    )\n                    NavigationBarItem(\n                        selected = tab == RootTab.SETTINGS,''')
