start=s.find('''\n        item(key = "refresh") {''')
if start>=0:
    end=s.find('\n        }\n',start)+11
    s=s[:start]+s[end:]
rep('''        AppQuickActionsDialog(\n            appName = displayName,''','''        val context = LocalContext.current\n        AppQuickActionsDialog(\n            appName = displayName,''')
rep('''            onRename = { editApp = liveSection to packageName; actionApp = null },\n            onDelete =''','''            onRename = { editApp = liveSection to packageName; actionApp = null },\n            onAppInfo = { openAppInfo(context, packageName); actionApp = null },\n            onDelete =''')
rep('private fun AppQuickActionsDialog(appName:String,onDismiss:()->Unit,onEdit:()->Unit,onRename:()->Unit,onDelete:()->Unit) {','private fun AppQuickActionsDialog(appName:String,onDismiss:()->Unit,onEdit:()->Unit,onRename:()->Unit,onAppInfo:()->Unit,onDelete:()->Unit) {')
rep('''            TextButton(onClick=onRename,modifier=Modifier.fillMaxWidth()) { Icon(Icons.Default.TextFields,null); Spacer(Modifier.width(8.dp)); Text("تغییر نام",modifier=Modifier.weight(1f),textAlign=TextAlign.Start) }\n            TextButton(onClick=onDelete''','''            TextButton(onClick=onRename,modifier=Modifier.fillMaxWidth()) { Icon(Icons.Default.TextFields,null); Spacer(Modifier.width(8.dp)); Text("تغییر نام",modifier=Modifier.weight(1f),textAlign=TextAlign.Start) }\n            TextButton(onClick=onAppInfo,modifier=Modifier.fillMaxWidth()) { Icon(Icons.Default.Info,null); Spacer(Modifier.width(8.dp)); Text("اطلاعات برنامه",modifier=Modifier.weight(1f),textAlign=TextAlign.Start) }\n            TextButton(onClick=onDelete''')
rep('''        shape = RoundedCornerShape(22.dp),\n        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),\n        border = BorderStroke(1.5.dp, accent.copy(alpha = 0.75f)),\n        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)\n    ) {\n        Box(\n            Modifier\n                .fillMaxWidth()\n                .height(4.dp)\n                .background(Brush.horizontalGradient(listOf(accent, accent.copy(alpha = 0.28f), Color.Transparent)))\n        )\n        Column(Modifier.padding(horizontal = 12.dp, vertical = 10.dp)) {''','''        shape = RoundedCornerShape(24.dp),\n        colors = CardDefaults.cardColors(containerColor = Color.Transparent),\n        border = BorderStroke(1.dp, accent.copy(alpha = 0.30f)),\n        elevation = CardDefaults.cardElevation(defaultElevation = 3.dp)\n    ) {\n        Box(\n            Modifier.fillMaxWidth().background(\n                Brush.linearGradient(listOf(accent.copy(alpha = 0.115f), MaterialTheme.colorScheme.surface, MaterialTheme.colorScheme.surface))\n            )\n        ) {\n        Column(Modifier.padding(horizontal = 13.dp, vertical = 11.dp)) {''')
rep('''                        fontWeight = FontWeight.ExtraBold,\n                        fontSize = 17.sp,''','''                        fontWeight = FontWeight.Black,\n                        fontSize = 17.sp,''')
rep('''                    if (section.packages.isNotEmpty()) {\n                        Text(\n                            "${section.packages.size} برنامه",\n                            color = MaterialTheme.colorScheme.onSurfaceVariant,\n                            fontSize = 11.sp\n                        )\n                    }\n                }\n                IconButton(onClick = onToggleCollapsed, modifier = Modifier.size(38.dp)) {''','''                    if (section.packages.isNotEmpty()) {\n                        Surface(shape = RoundedCornerShape(999.dp), color = accent.copy(alpha = 0.10f)) {\n                            Text("${section.packages.size} برنامه", Modifier.padding(horizontal = 8.dp, vertical = 2.dp), color = accent, fontSize = 10.sp, fontWeight = FontWeight.Bold)\n                        }\n                    }\n                }\n                IconButton(onClick = onAddClick, modifier = Modifier.size(36.dp)) {\n                    Icon(Icons.Default.Add, contentDescription = "افزودن برنامه", tint = accent)\n                }\n                IconButton(onClick = onToggleCollapsed, modifier = Modifier.size(36.dp)) {''')
s=s.replace('''                IconButton(onClick = onEditClick, modifier = Modifier.size(38.dp)) {\n                    Icon(Icons.Default.Edit, contentDescription = "ویرایش بخش")\n                }\n''','',1)
rep('''                    DropdownMenu(expanded = menuOpen, onDismissRequest = { menuOpen = false }) {\n                        DropdownMenuItem(\n                            text = { Text("افزودن برنامه") },''','''                    DropdownMenu(expanded = menuOpen, onDismissRequest = { menuOpen = false }) {\n                        DropdownMenuItem(text = { Text("ویرایش بخش") }, leadingIcon = { Icon(Icons.Default.Edit, null) }, onClick = { menuOpen = false; onEditClick() })\n                        DropdownMenuItem(\n                            text = { Text("افزودن برنامه") },''')
rep('''        }\n    }\n}\n\n@Composable\nprivate fun AppGrid(''','''        }\n        }\n    }\n}\n\n@Composable\nprivate fun AppGrid(''')
marker='''@Composable\nprivate fun SectionEditorDialog('''
helper='''private fun openAppInfo(context: Context, packageName: String) {\n    runCatching {\n        context.startActivity(Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {\n            data = Uri.parse("package:$packageName")\n            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n        })\n    }.onFailure { Toast.makeText(context, "اطلاعات این برنامه در دسترس نیست.", Toast.LENGTH_SHORT).show() }\n}\n\n'''
rep(marker,helper+marker)
marker='''@Composable\nprivate fun SettingsScreen('''
search='''@Composable\nprivate fun QuickSearchScreen(modifier: Modifier, sections: List<AppSection>, installedApps: List<InstalledApp>, appsLoading: Boolean) {\n    var query by remember { mutableStateOf("") }\n    val aliases = remember(sections) { buildMap<String,String> { sections.forEach { sec -> sec.aliases.forEach { (pkg,a) -> if(a.isNotBlank() && pkg !in this) put(pkg,a) } } } }\n    val sectionNames = remember(sections) { buildMap<String,String> { sections.forEach { sec -> sec.packages.forEach { pkg -> put(pkg, get(pkg)?.let { "$it، ${sec.title}" } ?: sec.title) } } } }\n    val normalized = remember(query) { normalizeSearch(query) }\n    val results = remember(installedApps, aliases, normalized) { if(normalized.isBlank()) installedApps.take(40) else installedApps.filter { it.searchText.contains(normalized) || normalizeSearch(aliases[it.packageName].orEmpty()).contains(normalized) }.take(80) }\n    LazyColumn(modifier.fillMaxSize().statusBarsPadding(), contentPadding=PaddingValues(14.dp,12.dp,14.dp,28.dp), verticalArrangement=Arrangement.spacedBy(10.dp)) {\n        item("search-head") { Column(verticalArrangement=Arrangement.spacedBy(10.dp)) {\n            Row(verticalAlignment=Alignment.CenterVertically) { Surface(CircleShape, color=MaterialTheme.colorScheme.primary.copy(alpha=.12f)) { Icon(Icons.Default.AutoAwesome,null,tint=MaterialTheme.colorScheme.primary,modifier=Modifier.padding(9.dp)) }; Spacer(Modifier.width(9.dp)); Column { Text("جستجوی سریع",fontWeight=FontWeight.Black,fontSize=20.sp); Text("نام اصلی یا نام دلخواه برنامه را بنویس",color=MaterialTheme.colorScheme.onSurfaceVariant,fontSize=11.sp) } }\n            OutlinedTextField(query,{query=it},Modifier.fillMaxWidth(),singleLine=true,leadingIcon={Icon(Icons.Default.Search,null)},placeholder={Text("جستجوی برنامه…")},shape=RoundedCornerShape(18.dp))\n        } }\n        if(appsLoading && installedApps.isEmpty()) item("loading") { Text("در حال آماده‌سازی فهرست برنامه‌ها…",color=MaterialTheme.colorScheme.onSurfaceVariant) }\n        else if(results.isEmpty()) item("empty-search") { Surface(shape=RoundedCornerShape(20.dp),color=MaterialTheme.colorScheme.surfaceVariant.copy(alpha=.55f),modifier=Modifier.fillMaxWidth()) { Text("برنامه‌ای پیدا نشد.",Modifier.padding(20.dp),textAlign=TextAlign.Center) } }\n        else items(results,key={it.packageName}) { app ->\n            val context=LocalContext.current; val name=aliases[app.packageName].orEmpty().ifBlank{app.label}; val sec=sectionNames[app.packageName].orEmpty()\n            Surface(shape=RoundedCornerShape(18.dp),color=MaterialTheme.colorScheme.surface,border=BorderStroke(1.dp,MaterialTheme.colorScheme.outline.copy(alpha=.14f)),modifier=Modifier.fillMaxWidth().combinedClickable(onClick={launchPackage(context,app.packageName)},onLongClick={openAppInfo(context,app.packageName)})) {\n                Row(Modifier.fillMaxWidth().padding(horizontal=12.dp,vertical=9.dp),verticalAlignment=Alignment.CenterVertically) { CachedAppIcon(app.packageName,name,sizeDp=42); Spacer(Modifier.width(11.dp)); Column(Modifier.weight(1f)) { Text(name,fontWeight=FontWeight.Bold,maxLines=1,overflow=TextOverflow.Ellipsis); if(name!=app.label) Text(app.label,color=MaterialTheme.colorScheme.onSurfaceVariant,fontSize=10.sp,maxLines=1); if(sec.isNotBlank()) Text(sec,color=MaterialTheme.colorScheme.primary,fontSize=10.sp,maxLines=1,overflow=TextOverflow.Ellipsis) }; Icon(Icons.Default.Search,null,tint=MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha=.55f),modifier=Modifier.size(18.dp)) }\n            }\n        }\n    }\n}\n\n'''
rep(marker,search+marker)
pos=s.index('private fun SettingsScreen('); tail=s[pos:]
tail=tail.replace('''    onCardRowsChange: (Int) -> Unit,\n    onMoveSection: (Long, Int) -> Unit\n) {''','''    onCardRowsChange: (Int) -> Unit,\n    onMoveSection: (Long, Int) -> Unit,\n    appsLoading: Boolean,\n    onRefreshApps: () -> Unit\n) {''',1); s=s[:pos]+tail
rep('''        item(key = "layout") {''','''        item(key = "catalog") {\n            Card(shape = RoundedCornerShape(22.dp)) { Row(Modifier.fillMaxWidth().padding(15.dp),verticalAlignment=Alignment.CenterVertically) {\n                Surface(CircleShape,color=MaterialTheme.colorScheme.secondary.copy(alpha=.12f)) { Icon(Icons.Default.Refresh,null,tint=MaterialTheme.colorScheme.secondary,modifier=Modifier.padding(10.dp)) }; Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text("فهرست برنامه‌های گوشی",fontWeight=FontWeight.ExtraBold,fontSize=16.sp); Text("پس از نصب یا حذف برنامه، AppDeck خودکار به‌روز می‌شود؛ این دکمه برای تازه‌سازی دستی است.",color=MaterialTheme.colorScheme.onSurfaceVariant,fontSize=11.sp) }; TextButton(onClick=onRefreshApps,enabled=!appsLoading) { Text(if(appsLoading) "در حال بررسی…" else "تازه‌سازی") }\n            } }\n        }\n\n        item(key = "layout") {''')
ui.write_text(s)
a=activity.read_text()
a=a.replace('import android.os.Bundle\n','import android.os.Bundle\nimport android.content.BroadcastReceiver\nimport android.content.Context\nimport android.content.Intent\nimport android.content.IntentFilter\nimport androidx.core.content.ContextCompat\n',1)
a=a.replace('''class MainActivity : ComponentActivity() {\n    private val viewModel by viewModels<MainViewModel>()\n''','''class MainActivity : ComponentActivity() {\n    private val viewModel by viewModels<MainViewModel>()\n    private var packageReceiverRegistered = false\n    private val packageReceiver = object : BroadcastReceiver() { override fun onReceive(context: Context?, intent: Intent?) { viewModel.refreshInstalledApps() } }\n''',1)
idx=a.rfind('\n}')
a=a[:idx]+'''\n    override fun onStart() {\n        super.onStart()\n        if (!packageReceiverRegistered) {\n            val filter = IntentFilter().apply { addAction(Intent.ACTION_PACKAGE_ADDED); addAction(Intent.ACTION_PACKAGE_REMOVED); addAction(Intent.ACTION_PACKAGE_REPLACED); addDataScheme("package") }\n            ContextCompat.registerReceiver(this, packageReceiver, filter, ContextCompat.RECEIVER_NOT_EXPORTED)\n            packageReceiverRegistered = true\n        }\n    }\n\n    override fun onStop() {\n        if (packageReceiverRegistered) { unregisterReceiver(packageReceiver); packageReceiverRegistered = false }\n        super.onStop()\n    }\n'''+a[idx:]
activity.write_text(a)
print('AppDeck V9 applied')
